/* Level 15 (Quartu) code following mobyutil; generated by tools/overlay_src.py, stubs replaced by C as functions are matched. Starts at 0x00248E58 (was mobyutil_00248E58.c). */
#include "common.h"
#include "include_asm.h"
#include "vector.h"
#include "moby.h"

typedef u32 u128 __attribute__((mode(TI), aligned(16)));
typedef int OvlQuad __attribute__((mode(TI)));
typedef struct {
    u8 pad0[0x18];
    s32 moby; /* 0x18: passed to FUN_002141f8 (reads moby+0x34, moby+0x78); 0 when no moby was hit */
    s32 unk1C; /* 0x1C: > 0 gates copying point and the normal into the hero (shared/ui/help/00226f10.c) */
    union {
        OvlQuad q;
        f32 f[4];
    } point; /* 0x20: f[2] is read as the ground height */
    u8 pad30[0x10]; /* 0x30: position after push-out (copied into hero.motion.pos) */
    f32 normal_x; /* 0x40: start of the surface normal; its angle is tested against 50 degrees (0.87266463) */
    f32 normal_y; /* 0x44: FUN_001f9e90 (atan2) of normal_x, normal_y is stored in the hero */
    f32 normal_z; /* 0x48: ledge probes compare atan2(normal_z, xy length) with 20 degrees */
} CollisionHit;
extern CollisionHit quartu_coll_hit;
extern int coll_sphere(void *, float, int, void *);
extern void FastVecAdd(void *, void *, void *);
extern void FastVecSub(void *, void *, void *);
extern f32 vec_length_xy(void *);
extern f32 fast_atan2(f32, f32);

/* Adapted from Lombyte's project (GPL-3.0) for PAL by OpenRAC's tools/port.py: src/overlays/l15/math/interpolation/00247e90.c, FUN_L15_00247e90. */
int move_moby_with_sphere_collision(struct Moby *obj, u128 *delta, int flags, float step, float radius) {
    Vec4 start;
    Vec4 probe;
    int pushed = 0;
    int i;
    int mask;

    qcopy(&start, &obj->pos);
    FastVecAdd(&obj->pos, &obj->pos, delta);
    i = 0;
    do {
        mask = (flags << 1) & 0x20;
        qcopy(&probe, &obj->pos);
        probe.f[2] += step;
        if (coll_sphere(&probe, radius, mask | 4, obj) == 0) {
            break;
        }
        if (fast_atan2(quartu_coll_hit.normal_z, vec_length_xy(&quartu_coll_hit.normal_x)) > 0.5235988f) {
            qcopy(&obj->pos, quartu_coll_hit.pad30);
            obj->pos.z -= step;
            pushed |= 1;
        }
        i++;
    } while (i < 6);
    FastVecSub(delta, &obj->pos, &start);
    return pushed;
}
